        "passed": true,
        "message": "build fixture passed",
        "duration": 9,
        "tool": "node"
      }
    },
    "controller": {
      "images": {
        "jenkins/jenkins:lab-core-1-jdk21": {
          "core": 1,
          "java": 21
        },
        "jenkins/jenkins:lab-core-2-jdk21": {
          "core": 2,
          "java": 21
        }
      },
      "plugins": {
        "configuration-as-code:lab-1": {
          "core": 1,
          "dependencies": {}
        },
        "git:lab-1": {
          "core": 1,
          "dependencies": {
            "git-client": "lab-1"
          }
        },
        "git-client:lab-1": {
          "core": 1,
          "dependencies": {}
        },
        "workflow-aggregator:lab-1": {
          "core": 1,
          "dependencies": {}
        },
        "configuration-as-code:lab-2": {
          "core": 2,
          "dependencies": {}
        },
        "git:lab-2": {
          "core": 2,
          "dependencies": {
            "git-client": "lab-2"
          }
        },
        "git-client:lab-2": {
          "core": 2,
          "dependencies": {}
        },
        "workflow-aggregator:lab-2": {
          "core": 2,
          "dependencies": {}
        }
      },
      "secretNames": [
        "JENKINS_ADMIN_PASSWORD"
      ],
      "bootHealthy": true,
      "initial": {
        "image": "jenkins/jenkins:lab-core-1-jdk21",
        "plugins": {
          "configuration-as-code": "lab-1",
          "git": "lab-1",
          "git-client": "lab-1",
          "workflow-aggregator": "lab-1"
        },
        "message": "Manual controller"
      },
      "expectedMessage": "Checkout controller managed by code",
      "expectedImage": "jenkins/jenkins:lab-core-2-jdk21",
      "expectedPlugins": {
        "configuration-as-code": "lab-2",
        "git": "lab-2",
        "git-client": "lab-2",
        "workflow-aggregator": "lab-2"
      }
    }
  },
  "cases": [
    {
      "id": "healthy",
      "title": "Healthy checkout",
      "description": "Healthy checkout. Inspect the stage and workspace evidence.",
      "jenkins": {}
    },
    {
      "id": "secret-unavailable",
      "title": "Runtime administrator reference is missing",
      "description": "Runtime administrator reference is missing. Inspect the stage and workspace evidence.",
      "jenkins": {
        "controller": {
